"""Native compatibility checks where consecutive complete Sections meet.

Paths POINT records use st_path_start/count/edge/rise plus, for each end,
st_path_start_seam or st_path_end_seam.  The base INT field is the partner
endpoint's global source vertex index, or -1 if this end has no Section seam.
Suffixes _neighbor and _edge hold the partner's adjacent source vertex and
terminal edge indices; _sign is +1 for opposite source ends and -1 for like
source ends; _rise is the partner's authored profile rise.  Binding compilation
only establishes these references.  GN reads all live positions and widths.
"""
import bpy
from .path_surface_nodes import _Nodes


NAME = 'Prochitecture Streets / Complete Section seam guards v1'


def build(*, local_diagnostics=False):
    name = NAME if not local_diagnostics else 'Prochitecture Streets / Local Section seam guards v2'
    existing = bpy.data.node_groups.get(name)
    if existing:
        return existing
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree')
    for name in ('Sources', 'Paths'):
        tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Valid', in_out='OUTPUT', socket_type='NodeSocketBool')
    if local_diagnostics:
        tree.interface.new_socket(name='Paths', in_out='OUTPUT', socket_type='NodeSocketGeometry')
    g = _Nodes(tree)
    inp = g.node('NodeGroupInput', 'Live source geometry and compiled Section seam bindings')
    out = g.node('NodeGroupOutput', 'Compatible endpoint profiles and tangent frames')
    sources, paths = inp.outputs['Sources'], inp.outputs['Paths']
    position = g.node('GeometryNodeInputPosition', 'Actual source position').outputs[0]
    source_size = g.node('GeometryNodeAttributeDomainSize', 'Source binding index limits')
    source_size.component = 'MESH'
    g.set(sources, source_size.inputs['Geometry'])
    path_size = g.node('GeometryNodeAttributeDomainSize', 'Empty seam tables are valid')
    path_size.component = 'MESH'
    g.set(paths, path_size.inputs['Geometry'])
    start = g.named('st_path_start')
    count = g.named('st_path_count')
    first_edge = g.named('st_path_edge')
    own_rise = g.named('st_path_rise', 'FLOAT')

    def bounds(index, size):
        return g.all(g.compare(index, 0, 'GREATER_EQUAL', 'INT'),
                     g.compare(index, size, 'LESS_THAN', 'INT'))

    def source_position(index):
        return g.sample(sources, position, index, 'FLOAT_VECTOR')

    def edge_value(name, index):
        return g.sample(sources, g.named(name, 'FLOAT'), index, 'FLOAT', 'EDGE')

    checks = []
    for suffix, own_endpoint, own_neighbor, own_edge in (
        ('start', start, g.math('ADD', start, 1.), first_edge),
        ('end', g.math('ADD', start, g.math('SUBTRACT', count, 1.)),
         g.math('ADD', start, g.math('SUBTRACT', count, 2.)),
         g.math('ADD', first_edge, g.math('SUBTRACT', count, 2.))),
    ):
        prefix = 'st_path_' + suffix + '_seam'
        partner_endpoint = g.named(prefix)
        partner_neighbor = g.named(prefix + '_neighbor')
        partner_edge = g.named(prefix + '_edge')
        sign = g.named(prefix + '_sign', 'FLOAT')
        partner_rise = g.named(prefix + '_rise', 'FLOAT')
        present = g.compare(partner_endpoint, 0, 'GREATER_EQUAL', 'INT')
        a, b = source_position(own_endpoint), source_position(partner_endpoint)
        direction = g.vector('SUBTRACT', source_position(own_neighbor), a)
        partner_direction = g.vector('SUBTRACT', source_position(partner_neighbor), b)
        opposing = g.vector('ADD', g.vector('NORMALIZE', direction),
                             g.vector('NORMALIZE', partner_direction))
        mode = g.sample(sources, g.named('st_interpolation'), own_edge, 'INT', 'EDGE')
        partner_mode = g.sample(sources, g.named('st_interpolation'), partner_edge, 'INT', 'EDGE')
        smooth = g.all(g.compare(mode, 3, 'EQUAL', 'INT'),
                       g.compare(partner_mode, 3, 'EQUAL', 'INT'))
        # Smooth paths share the bisector of their two incident directed
        # chords. Exact paths retain the earlier straight-seam contract.
        aligned = g.switch(smooth,
            g.compare(g.vector('LENGTH', opposing), 1e-5, 'LESS_EQUAL'),
            g.compare(g.vector('DOT_PRODUCT', g.vector('NORMALIZE', direction),
                g.vector('NORMALIZE', partner_direction)), .875, 'LESS_THAN'), 'BOOLEAN')
        width = edge_value('st_width', own_edge)
        partner_width = edge_value('st_width', partner_edge)
        offset = edge_value('st_offset', own_edge)
        partner_offset = edge_value('st_offset', partner_edge)
        transition = g.named('st_path_'+suffix+'_transition')
        taper = g.all(transition.node.outputs['Exists'], g.compare(transition, 0, 'GREATER_EQUAL', 'INT'))
        dimensions = g.all(g.close(width, partner_width, 1e-6),
            g.close(offset, g.math('MULTIPLY', sign, partner_offset), 1e-6))
        valid = g.all(
            bounds(partner_endpoint, source_size.outputs['Point Count']),
            bounds(partner_neighbor, source_size.outputs['Point Count']),
            bounds(partner_edge, source_size.outputs['Edge Count']),
            g.compare(g.vector('DISTANCE', a, b), 2e-5, 'LESS_EQUAL'),
            g.compare(g.vector('LENGTH', direction), 1e-4, 'GREATER_THAN'),
            g.compare(g.vector('LENGTH', partner_direction), 1e-4, 'GREATER_THAN'),
            aligned,
            g.compare(mode, partner_mode, 'EQUAL', 'INT'),
            g.compare(width, 0., 'GREATER_THAN'),
            g.either(taper, dimensions),
            g.compare(partner_width, .001, 'GREATER_THAN'),
            g.close(g.math('ABSOLUTE', sign), 1., 1e-6),
            g.close(own_rise, partner_rise, 1e-6),
        )
        checks.append(g.switch(present, True, valid, 'BOOLEAN', suffix + ' seam compatibility'))
    all_rows = g.stat(paths, g.all(*checks))
    empty = g.compare(path_size.outputs['Point Count'], 0, 'EQUAL', 'INT')
    g.set(g.either(empty, all_rows), out.inputs['Valid'])
    if local_diagnostics:
        g.set(g.store(paths, 'st_path_seam_valid', g.all(*checks), 'BOOLEAN'), out.inputs['Paths'])
    tree['construction'] = 'Direct live endpoint, tangent, width, signed offset and profile-rise checks between complete Sections'
    return tree
